const input = $json.evaluation_input ?? $json;
const profile = input.profile ?? {};
const normalizeText = value => String(value ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const asNumber = value => { const match = String(value ?? '').replace(',', '.').match(/-?\d+(?:\.\d+)?/); return match ? Number(match[0]) : NaN; };
const asMonths = value => { const number = asNumber(value); return Number.isFinite(number) && /\b(ano|anos)\b/.test(normalizeText(value)) ? number * 12 : number; };
const ruleResults = (input.questions ?? []).map(item => { const question = item.question ?? {}; const value = item.normalized ?? item.answer ?? ''; const config = question.answer_config ?? {}; const accepted = (question.accepted_answers ?? []).map(normalizeText); let passed = true; let reason = 'Respuesta recibida'; if (question.hard_fail && accepted.length) { passed = accepted.includes(normalizeText(value)); reason = passed ? 'Coincide con una respuesta aceptada' : `No coincide con las respuestas aceptadas: ${(question.accepted_answers ?? []).join(', ')}`; } const numeric = asNumber(value); const months = asMonths(value); if (passed && Number.isFinite(numeric) && config.min != null && numeric < Number(config.min)) { passed = false; reason = `Valor menor que el mínimo ${config.min}`; } if (passed && Number.isFinite(numeric) && config.max != null && numeric > Number(config.max)) { passed = false; reason = `Valor mayor que el máximo ${config.max}`; } if (passed && Number.isFinite(months) && config.minMonths != null && months < Number(config.minMonths)) { passed = false; reason = `Experiencia menor que ${config.minMonths} meses`; } if (passed && Number.isFinite(months) && config.maxMonths != null && months > Number(config.maxMonths)) { passed = false; reason = `Experiencia mayor que ${config.maxMonths} meses`; } return { question_id: question.id, field_key: question.field_key, label: question.label, passed, hardFail: Boolean(question.hard_fail), result: passed ? 'passed' : 'failed', reason }; });
const hardFails = ruleResults.filter(item => item.hardFail && !item.passed);
const experienceQuestion = (input.questions ?? []).find(item => /experiencia|años|meses/i.test(String(item.question?.field_key ?? item.question?.label ?? '')));
const experienceMonths = experienceQuestion ? asMonths(experienceQuestion.normalized ?? experienceQuestion.answer ?? '') : NaN;
const profileExperienceFail = Number.isFinite(experienceMonths) && profile.experience_years_min != null && experienceMonths < Number(profile.experience_years_min) * 12;
const answers = (input.questions ?? []).map(item => ({ key: String(item.question?.field_key ?? item.question?.label ?? ''), text: String(item.normalized ?? item.answer ?? '') }));
const answerText = answers.map(item => `${item.key}: ${item.text}`).join(' | ').toLowerCase();
const profileChecks = [];
if (profileExperienceFail) profileChecks.push(`Experiencia inferior al mínimo del perfil: ${profile.experience_years_min} años`);
for (const requirement of Array.isArray(profile.required_requirements) ? profile.required_requirements : []) if (requirement && !answerText.includes(String(requirement).toLowerCase())) profileChecks.push(`Requisito no evidenciado: ${requirement}`);
for (const license of Array.isArray(profile.licenses) ? profile.licenses : []) if (license && !answerText.includes(String(license).toLowerCase())) profileChecks.push(`Licencia no evidenciada: ${license}`);
for (const language of Array.isArray(profile.languages) ? profile.languages : []) if (language && !answerText.includes(String(language).toLowerCase())) profileChecks.push(`Idioma no evidenciado: ${language}`);
if (profile.academic_level && !answerText.includes(String(profile.academic_level).toLowerCase())) profileChecks.push(`Nivel académico no evidenciado: ${profile.academic_level}`);
if (profile.location && !answerText.includes(String(profile.location).toLowerCase())) profileChecks.push(`Ubicación requerida no evidenciada: ${profile.location}`);
return [{ json: { ...input, deterministic: { passed: hardFails.length === 0 && profileChecks.length === 0, hardFails: [...hardFails.map(item => item.label), ...profileChecks], ruleResults, profileChecks, profileCriteria: { required_requirements: profile.required_requirements ?? [], academic_level: profile.academic_level ?? null, ai_criteria: profile.ai_criteria ?? null, licenses: profile.licenses ?? [], languages: profile.languages ?? [], location: profile.location ?? null } } } }];
